draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // pyramid base (physiological needs)
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.rect(W/2 - 100, H - 50, 200, 50);
  ctx.stroke();
  ctx.fill();
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Physiological', W/2, H - 25);

  // pyramid second level (safety needs)
  ctx.beginPath();
  ctx.rect(W/2 - 80, H - 150, 160, 50);
  ctx.stroke();
  ctx.fill();
  ctx.fillText('Safety', W/2, H - 125);

  // pyramid third level (love and belonging needs)
  ctx.beginPath();
  ctx.rect(W/2 - 50, H - 250, 100, 50);
  ctx.stroke();
  ctx.fill();
  ctx.fillText('Love & Belonging', W/2, H - 225);

  // pyramid fourth level (esteem needs)
  ctx.beginPath();
  ctx.rect(W/2 - 20, H - 350, 40, 50);
  ctx.stroke();
  ctx.fill();
  ctx.fillText('Esteem', W/2, H - 325);

  // pyramid top (self-actualization needs)
  ctx.beginPath();
  ctx.arc(W/2, H - 420 + 20 * Math.sin(t), 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fill();
  ctx.fillText('Self-Actualization', W/2, H - 395 + 20 * Math.sin(t));

  ctx.restore();
}
